302     //  Refill FSM
303     //  {{{
304 
305     //      ask permission to the refill arbiter if there is a pending refill
306     assign refill_req_valid_o  = refill_fsm_q == REFILL_IDLE ? refill_fifo_resp_meta_rok : 1'b0;
307 
308     always_comb
309     begin : miss_resp_fsm_comb
310         refill_updt_sel_victim_o = 1'b0;
311         refill_set_o            = '0;
312         refill_way              = '0;
313         refill_write_dir_o      = 1'b0;
314         refill_write_data_o     = 1'b0;
315         refill_updt_rtab_o      = 1'b0;
316         refill_cnt_d            = refill_cnt_q;
317 
318         inval_check_dir_o       = 1'b0;
319         inval_write_dir_o       = 1'b0;
320 
321         refill_core_rsp_valid   = 1'b0;
322         refill_core_rsp_sid     = '0;
323         refill_core_rsp_tid     = '0;
324         refill_core_rsp_error   = 1'b0;
325         refill_core_rsp_word    = 0;
326 
327         refill_fifo_resp_meta_r = 1'b0;
328         refill_fifo_resp_data_r = 1'b0;
329 
330         mshr_ack_cs             = 1'b0;
331         mshr_ack                = 1'b0;
332 
333         refill_fsm_d            = refill_fsm_q;
334 
335         case (refill_fsm_q)
336             //  Wait for refill responses
337             //  {{{
338             REFILL_IDLE: begin
339                 if (refill_fifo_resp_meta_rok) begin
340                     //  anticipate the activation of the MSHR independently of the grant signal from
341                     //  the refill arbiter. This is to avoid the introduction of unnecessary timing
342                     //  paths (however there could be a minor augmentation of the power consumption)
343                     mshr_ack_cs = ~refill_fifo_resp_meta_rdata.is_inval;
344 
345                     //  if the permission is granted, start refilling
346                     if (refill_req_ready_i) begin
347                         refill_set_o = mshr_ack_cache_set;
348 
349                         if (refill_fifo_resp_meta_rdata.is_inval) begin
350                             //  check for a match with the line being invalidated in the cache dir
351                             inval_check_dir_o = 1'b1;
352 
353                             refill_fsm_d = REFILL_INVAL;
354                         end else begin
355                             //  read the MSHR and reset the valid bit for the corresponding entry
356                             mshr_ack = ~refill_fifo_resp_meta_rdata.is_inval;
357 
358                             //  initialize the counter for refill words
359                             refill_cnt_d = 0;
360                             refill_fsm_d = REFILL_WRITE;
361                         end
362                     end
363                 end
364             end
365             //  }}}
366 
367             //  Write refill data into the cache
368             //  {{{
369             REFILL_WRITE: begin
370                 automatic logic is_prefetch;
371                 automatic hpdcache_uint core_rsp_word;
372 
373                 //  Respond to the core (when needed)
374                 if (refill_cnt_q == 0) begin
375                     core_rsp_word = hpdcache_uint'(mshr_ack_word)/HPDcacheCfg.u.accessWords;
