165         cmoh_flush_req_valid_d = cmoh_flush_req_valid_q;
166         cmoh_flush_req_set_d   = cmoh_flush_req_set_q;
167         cmoh_flush_req_way_d   = cmoh_flush_req_way_q;
168         cmoh_flush_req_inval_d = cmoh_flush_req_inval_q;
169 
170         cmoh_set_incr  = 1'b0;
171         cmoh_set_reset = 1'b0;
172         cmoh_way_incr  = 1'b0;
173         cmoh_way_reset = 1'b0;
174 
175         dir_check_nline_o     = 1'b0;
176         dir_check_nline_set_o = cmoh_set;
177         dir_check_nline_tag_o = cmoh_tag;
178         dir_check_entry_o     = 1'b0;
179         dir_check_entry_set_o = cmoh_set_q;
180         dir_check_entry_way_o = cmoh_way_q;
181 
182         dir_inval_o     = 1'b0;
183         dir_inval_set_o = cmoh_set_q;
184         dir_inval_way_o = '0;
185 
186         wbuf_flush_all_o = 1'b0;
187 
188         cmoh_flush_req_w   = 1'b0;
189         cmoh_flush_req_set = '0;
190         cmoh_flush_req_way = '0;
191         cmoh_flush_req_tag = '0;
192 
193         cmoh_fsm_d = cmoh_fsm_q;
194 
195         unique case (cmoh_fsm_q)
196             CMOH_IDLE: begin
197                 if (req_valid_i) begin
198                     unique case (1'b1)
199                         req_op_i.is_fence: begin
200                             //  request to the write buffer to send all open entries
201                             wbuf_flush_all_o = rtab_empty_i;
202 
203                             //  then wait for the write buffer to be empty
204                             if (!rtab_empty_i || !wbuf_empty_i) begin
205                                 cmoh_fsm_d = CMOH_FENCE_WAIT_WBUF_RTAB_EMPTY;
206                             end
207                         end
208 
209                         req_op_i.is_inval_by_nline,
210                         req_op_i.is_inval_all,
211                         req_op_i.is_flush_by_nline,
212                         req_op_i.is_flush_all,
213                         req_op_i.is_flush_inval_by_nline,
214                         req_op_i.is_flush_inval_all: begin
215                             cmoh_op_d      = req_op_i;
216                             cmoh_addr_d    = req_addr_i;
217                             cmoh_way_reset = 1'b1;
218                             cmoh_set_reset = 1'b1;
219                             if (mshr_empty_i && rtab_empty_i && ctrl_empty_i) begin // CMO
220                                 unique if (req_op_i.is_inval_by_nline) begin
221                                     cmoh_fsm_d = CMOH_INVAL_CHECK_NLINE;
222                                 end else if (req_op_i.is_inval_all) begin
223                                     cmoh_fsm_d = CMOH_INVAL_SET;
224                                 end else if (req_op_i.is_flush_by_nline) begin
225                                     cmoh_flush_req_inval_d = 1'b0;
226                                     cmoh_fsm_d = CMOH_FLUSH_NLINE_FIRST;
227                                 end else if (req_op_i.is_flush_all) begin
228                                     cmoh_flush_req_inval_d = 1'b0;
229                                     cmoh_fsm_d = CMOH_FLUSH_ALL_FIRST;
230                                 end else if (req_op_i.is_flush_inval_by_nline) begin
231                                     cmoh_flush_req_inval_d = 1'b1;
232                                     cmoh_fsm_d = CMOH_FLUSH_NLINE_FIRST;
233                                 end else if (req_op_i.is_flush_inval_all) begin
234                                     cmoh_flush_req_inval_d = 1'b1;
235                                     cmoh_fsm_d = CMOH_FLUSH_ALL_FIRST;
236                                 end
237                             end else begin
238                                 cmoh_fsm_d = CMOH_WAIT_MSHR_RTAB_EMPTY;
239                             end
240                         end
241                     endcase
242                 end
243             end
244             CMOH_FENCE_WAIT_WBUF_RTAB_EMPTY: begin
245                 wbuf_flush_all_o = rtab_empty_i;
246                 if (wbuf_empty_i && rtab_empty_i) begin
247                     cmoh_fsm_d = CMOH_IDLE;
248                 end
249             end
250             CMOH_WAIT_MSHR_RTAB_EMPTY: begin
251                 if (mshr_empty_i && rtab_empty_i && ctrl_empty_i) begin
252                     unique if (cmoh_op_q.is_inval_by_nline) begin
253                         cmoh_fsm_d = CMOH_INVAL_CHECK_NLINE;
254                     end else if (cmoh_op_q.is_inval_all) begin
255                         cmoh_fsm_d = CMOH_INVAL_SET;
256                     end else if (cmoh_op_q.is_flush_by_nline) begin
257                         cmoh_flush_req_inval_d = 1'b0;
258                         cmoh_fsm_d = CMOH_FLUSH_NLINE_FIRST;
259                     end else if (cmoh_op_q.is_flush_all) begin
260                         cmoh_flush_req_inval_d = 1'b0;
261                         cmoh_fsm_d = CMOH_FLUSH_ALL_FIRST;
262                     end else if (cmoh_op_q.is_flush_inval_by_nline) begin
263                         cmoh_flush_req_inval_d = 1'b1;
264                         cmoh_fsm_d = CMOH_FLUSH_NLINE_FIRST;
265                     end else if (cmoh_op_q.is_flush_inval_all) begin
266                         cmoh_flush_req_inval_d = 1'b1;
267                         cmoh_fsm_d = CMOH_FLUSH_ALL_FIRST;
268                     end
269                 end
270             end
271             CMOH_INVAL_CHECK_NLINE: begin
272                 dir_check_nline_o = 1'b1;
273                 cmoh_fsm_d = CMOH_INVAL_SET;
274             end
275             CMOH_INVAL_SET: begin
276                 unique case (1'b1)
277                     //  The CMO requests the invalidation of a given cacheline (or flush with
278                     //  invalidation when the cache does not support WB policy)
279                     cmoh_op_q.is_inval_by_nline,
280                     cmoh_op_q.is_flush_inval_by_nline: begin
281                         /* FIXME this adds a DIR to DIR timing path. We should probably delay the
282                          *       invalidation of one cycle to ease the timing closure */
283                         dir_inval_o     = cmoh_dir_check_nline_hit;
284                         dir_inval_way_o = dir_check_nline_hit_way_i;
285                         cmoh_fsm_d      = CMOH_IDLE;
286                     end
287 
288                     //  The CMO requests a full invalidation (or flush with invalidation when the
289                     //  cache does not support WB policy)
290                     cmoh_op_q.is_inval_all,
291                     cmoh_op_q.is_flush_inval_all:
292                     begin
293                         dir_inval_o     = 1'b1;
294                         dir_inval_way_o = {HPDcacheCfg.u.ways{1'b1}};
295                         dir_inval_set_o = cmoh_set_q;
296                         cmoh_set_incr   = 1'b1;
297                         if (cmoh_set_last) begin
298                             cmoh_fsm_d = CMOH_IDLE;
299                         end
300                     end
301                 endcase
302             end
303             CMOH_FLUSH_ALL_FIRST: begin
304                 if (HPDcacheCfg.u.wbEn) begin
305                     if (cmoh_flush_req_wok) begin
306                         dir_check_entry_o = 1'b1;
307                         cmoh_set_incr = cmoh_way_last;
308                         cmoh_way_incr = 1'b1;
309                         cmoh_flush_req_valid_d = 1'b1;
310                         cmoh_flush_req_set_d = cmoh_set_q;
311                         cmoh_flush_req_way_d = cmoh_way_q;
312                         cmoh_fsm_d = CMOH_FLUSH_ALL_NEXT;
313                     end
314                 end else if (cmoh_flush_req_inval_q) begin
315                     cmoh_fsm_d = CMOH_INVAL_SET;
316                 end else begin
317                     cmoh_fsm_d = CMOH_IDLE;
318                 end
319             end
320             CMOH_FLUSH_ALL_NEXT: begin
321                 if (cmoh_flush_req_valid_q) begin
322                     dir_inval_o = cmoh_flush_req_inval_q;
323                     dir_inval_set_o = cmoh_flush_req_set_q;
324                     dir_inval_way_o = cmoh_flush_req_way_q;
325                     cmoh_flush_req_w = dir_check_entry_valid_i & dir_check_entry_dirty_i;
326                     cmoh_flush_req_set = cmoh_flush_req_set_q;
327                     cmoh_flush_req_way = cmoh_flush_req_way_q;
328                     cmoh_flush_req_tag = dir_check_entry_tag_i;
329 
330                     //  In case of invalidation, the CMO handler needs to dedicate one cycle to
331                     //  check the directory and one cycle to invalidate that entry.
332                     //  This means that the CMO handler takes 2 cycles per flush request
333                     cmoh_flush_req_valid_d = ~cmoh_flush_req_inval_q;
334                 end
335 
336                 if ((!cmoh_flush_req_valid_q || !cmoh_flush_req_inval_q) && cmoh_flush_req_wok)
337                 begin
338                     dir_check_entry_o = 1'b1;
339                     cmoh_set_incr = cmoh_way_last;
340                     cmoh_way_incr = 1'b1;
341                     cmoh_flush_req_valid_d = 1'b1;
342                     cmoh_flush_req_set_d = cmoh_set_q;
343                     cmoh_flush_req_way_d = cmoh_way_q;
344 
345                     if (cmoh_set_last && cmoh_way_last) begin
346                         cmoh_fsm_d = CMOH_FLUSH_ALL_LAST;
347                     end
348                 end
349             end
